  "mainEntity": [
    {
      "@type": "Question",
      "name": "Does the Godox VK2-LT vlog kit work with iPhone 15 or iPhone 16?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "No. The Godox VK2-LT uses a Lightning-connector microphone, and iPhone 15 and later models switched to USB-C. You would need the Godox VK2-UC variant instead. The LED6Bi light, MT03 tripod, and MTH02 clamp work with any phone."
      }
    },
    {
      "@type": "Question",
      "name": "How long does the Godox VK2-LT LED light battery last?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "The LED6Bi's 1800mAh battery lasts approximately 1.5 hours at 100 percent brightness and up to 10 hours at the lowest setting. It recharges via USB-C in about two hours."
      }
    },
    {
      "@type": "Question",
      "name": "Can the Godox VK2-LT kit be used with a phone case on?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. The MTH02 phone clamp supports widths from 6.1cm to 8.9cm, which accommodates most iPhones with a slim to medium-thickness case. Very thick rugged cases may need to be removed for a secure grip."
      }
    },
    {
      "@type": "Question",
      "name": "Is the Godox VK2-LT better than using just the iPhone built-in mic and camera?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Significantly better. The Geniusmic LT provides clearer, more directional audio with less background noise than the iPhone's built-in microphones. The LED6Bi light adds proper fill lighting that eliminates the grainy look of low-light phone video."
      }
    },
    {
      "@type": "Question",
      "name": "What is the price of the Godox VK2-LT vlog kit for iPhone?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "The Godox VK2-LT retails for approximately $119. Competing all-in-one kits like the Rode Vlogger Kit ($149) and the Joby GorillaPod Mobile Kit ($220) are priced higher, making the VK2-LT one of the best value options in the budget vlogging category."
      }
    }
  ]
}
